#include <furi.h>
#include <gui/gui.h> /* importing GUI function */

/* generated by fbt from .png files in images folder */
#include <pokegatchi_icons.h>

/* is the app running? */
typedef struct {
    bool running;
    int square_pos;
} AppState;

/* drawing canvas on screen stuff*/
static void draw_callback(Canvas* canvas, void* ctx) {
    AppState* state = ctx;
    canvas_draw_box(canvas, state->square_pos, 28, 8, 8);
}

/* button stuff*/
static void input_callback(InputEvent* event, void* ctx) {
    AppState* state = ctx;
    if(event->type == InputTypePress) {
        if(event->key == InputKeyBack) {
            state->running = false;
        }
        if(event->key == InputKeyRight) {
            state->square_pos = state->square_pos + 1;
        }
        if(event->key == InputKeyLeft) {
            state->square_pos = state->square_pos - 1;
        }
    }
}

int32_t pokegatchi_app(void* p) {
    UNUSED(p);
    AppState state;
    state.running = true;
    state.square_pos = 60;
    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, draw_callback, &state);
    view_port_input_callback_set(view_port, input_callback, &state);
    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    while(state.running) {
        view_port_update(view_port);
        furi_delay_ms(50);
    }

    gui_remove_view_port(gui, view_port);
    view_port_free(view_port);
    furi_record_close(RECORD_GUI);
    return 0;
}
